/**
 * Work items in lanes. Each lane has a title, a count and its cards; a card has a title, an optional tag and the
 * person it belongs to. Axes: card (simple, detail: tag and person), cols (2, 3), tone, density. Moving a card
 * between lanes is a port contract.
 */
import { type ReactNode } from "react";
import { Grid, Group, List, ListItem, Stack, Text, Title } from "../compose";
import { EmptyState } from "../components/empty-state";
import { Pill } from "../components/pill";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl } from "../utils";
import type { Lane, BoardCard } from "./kanban-board.types";

export type KanbanBoardProps = {
  id: string;
  title: string;
  lanes: Lane[];
  empty?: string;
  cards: BoardCard[];
  countLabel: string;
  card?: "simple" | "detail";
  cols?: "2" | "3";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function KanbanBoard({
  id,
  title,
  lanes,
  empty = "",
  cards,
  countLabel,
  card = "detail",
  cols = "3",
  tone = "default",
  density = "default",
  landmarkLabel,
}: KanbanBoardProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} landmarkLabel={landmarkLabel}>
      {((lanes?.length ?? 0) === 0) ? (
        <EmptyState icon="kanban" title={empty} />
      ) : (
        <Grid cols={(((cols as string) === "2") ? "1-2" : "1-3")} className="items-start gap-4" data-slot="lanes">
          {(lanes ?? []).map((lane) => (
            <Stack key={lane.id} gap="4" align="stretch" className="rounded bg-muted p-4" data-slot="lane">
              <Group gap="2" align="center" justify="between">
                <Title as={3} size="base" weight="bold">
                  {lane.title}
                </Title>
                <Text size="xs" className="text-muted-foreground">
                  {tpl(countLabel, (cards.filter((i) => !lane.key || i["lane"] === lane.key)?.length ?? 0))}
                </Text>
              </Group>
              <List className="m-0 flex list-none flex-col gap-2 p-0">
                {(cards.filter((i) => !lane.key || i["lane"] === lane.key) ?? []).map((c) => (
                  <ListItem key={c.id}
                    className={cn(
                      "flex flex-col rounded bg-card inset-ring inset-ring-border",
                      (((density as string) === "compact") ? "gap-2 p-2" : "gap-2 p-4")
                    )}
                    data-slot="item"
                  >
                    <Text size="sm" weight="semibold">
                      {c.title}
                    </Text>
                    {((card as string) === "detail") ? (
                      <Group gap="2" align="center" justify="between" className="flex-wrap">
                        <Pill tone="blue" icon="tag">
                          {c.tag}
                        </Pill>
                        <Text size="xs" className="text-muted-foreground">
                          {c.who}
                        </Text>
                      </Group>
                    ) : null}
                  </ListItem>
                ))}
              </List>
            </Stack>
          ))}
        </Grid>
      )}
    </SectionFrame>
  );
}

